CREATE TABLE classroom_shared_message_themes(classroom_id UUID PRIMARY KEY REFERENCES classrooms(id) ON DELETE CASCADE,theme TEXT NOT NULL CHECK(theme IN ('violet','lavender','ocean','sage','rose','midnight')),updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE conversation_shared_message_themes(conversation_id UUID PRIMARY KEY REFERENCES classroom_conversations(id) ON DELETE CASCADE,theme TEXT NOT NULL CHECK(theme IN ('violet','lavender','ocean','sage','rose','midnight')),updated_by UUID REFERENCES users(id) ON DELETE SET NULL,updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO classroom_shared_message_themes(classroom_id,theme,updated_by) SELECT DISTINCT ON(t.classroom_id) t.classroom_id,t.theme,t.user_id FROM classroom_message_themes t JOIN classrooms cl ON cl.id=t.classroom_id ORDER BY t.classroom_id,(t.user_id=cl.owner_id) DESC,t.user_id;
INSERT INTO conversation_shared_message_themes(conversation_id,theme,updated_by) SELECT DISTINCT ON(conversation_id) conversation_id,theme,user_id FROM conversation_message_themes ORDER BY conversation_id,user_id;
CREATE TABLE classroom_message_reactions(message_id BIGINT REFERENCES classroom_messages(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,emoji TEXT NOT NULL CHECK(emoji IN ('👍','❤️','😂','😮','😢','🙏','🎉','🔥','✅','👀')),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(message_id,user_id));
